function solve(n, edges, source) {
  const jarak = Array(n).fill(Infinity)
  const selesai = Array(n).fill(false)
  jarak[source] = 0
  for (let k = 0; k < n; k++) {
    // EXTRACT-MIN: simpul terdekat yang belum final.
    let u = -1
    for (let i = 0; i < n; i++) {
      if (selesai[i]) continue
      if (u === -1 || jarak[i] < jarak[u]) u = i
    }
    if (jarak[u] === Infinity) break // sisanya tak terjangkau
    selesai[u] = true
    for (const [a, b, w] of edges) {
      if (a === u && jarak[u] + w < jarak[b]) {
        jarak[b] = jarak[u] + w
      }
    }
  }
  return jarak.map((d) => (d === Infinity ? -1 : d))
}
